CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE TABLE IF NOT EXISTS leads(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),business_name TEXT NOT NULL,website_url TEXT,phone TEXT,address TEXT,google_place_id TEXT UNIQUE,niche TEXT NOT NULL,location TEXT NOT NULL,status TEXT DEFAULT 'Discovered' CHECK(status IN('Discovered','Enriched','Contacted')),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS lead_enrichments(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),lead_id UUID UNIQUE REFERENCES leads(id) ON DELETE CASCADE,pagespeed_score INT,pagespeed_issues JSONB DEFAULT '[]',website_audit_notes TEXT,visual_design_flaws JSONB DEFAULT '[]',decision_makers JSONB DEFAULT '[]',value_proposition_angle TEXT,updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS email_accounts(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),provider TEXT NOT NULL CHECK(provider IN('gmail','microsoft','smtp')),email_address TEXT NOT NULL UNIQUE,access_token TEXT,refresh_token TEXT,token_expires_at TIMESTAMPTZ,is_active BOOLEAN DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS outreach_templates(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),name TEXT NOT NULL,goal TEXT NOT NULL,subject_template TEXT NOT NULL,body_template TEXT NOT NULL,variables JSONB DEFAULT '[]',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS inbox_drafts_and_feedback(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),lead_id UUID REFERENCES leads(id) ON DELETE CASCADE,email_account_id UUID REFERENCES email_accounts(id) ON DELETE SET NULL,provider_message_id TEXT UNIQUE,sender_email TEXT,incoming_subject TEXT,incoming_message TEXT NOT NULL,sentiment TEXT CHECK(sentiment IN('Interested','Objection','Unsubscribe','Meeting Request','Other')),proposed_draft TEXT NOT NULL,user_tweaks TEXT,final_version TEXT,status TEXT DEFAULT 'Pending' CHECK(status IN('Pending','Approved','Sent')),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS generated_websites(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),prompt TEXT NOT NULL,component_code TEXT NOT NULL,github_repo_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS call_queue(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),lead_id UUID NOT NULL UNIQUE REFERENCES leads(id) ON DELETE CASCADE,website_url TEXT,maps_url TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Not Called' CHECK(status IN('Not Called','Attempted','Connected','Follow Up','Do Not Call')),notes TEXT NOT NULL DEFAULT '',last_called_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_leads_place_id ON leads(google_place_id);CREATE INDEX IF NOT EXISTS idx_leads_status ON leads(status);CREATE INDEX IF NOT EXISTS idx_enrichments_lead_id ON lead_enrichments(lead_id);CREATE INDEX IF NOT EXISTS idx_inbox_status ON inbox_drafts_and_feedback(status);CREATE INDEX IF NOT EXISTS idx_call_queue_status ON call_queue(status);
ALTER TABLE leads ENABLE ROW LEVEL SECURITY;ALTER TABLE lead_enrichments ENABLE ROW LEVEL SECURITY;ALTER TABLE email_accounts ENABLE ROW LEVEL SECURITY;ALTER TABLE outreach_templates ENABLE ROW LEVEL SECURITY;ALTER TABLE inbox_drafts_and_feedback ENABLE ROW LEVEL SECURITY;ALTER TABLE generated_websites ENABLE ROW LEVEL SECURITY;ALTER TABLE call_queue ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION normalize_lead_address(value TEXT) RETURNS TEXT LANGUAGE SQL IMMUTABLE PARALLEL SAFE AS $$ SELECT CASE WHEN value IS NULL THEN NULL ELSE lower(regexp_replace(regexp_replace(value, '\m(united kingdom|uk|great britain)\M', '', 'gi'), '[^a-zA-Z0-9]', '', 'g')) END $$;
CREATE OR REPLACE FUNCTION normalize_lead_phone(value TEXT) RETURNS TEXT LANGUAGE SQL IMMUTABLE PARALLEL SAFE AS $$ SELECT CASE WHEN value IS NULL THEN NULL WHEN regexp_replace(value, '[^0-9]', '', 'g') LIKE '00%' THEN substring(regexp_replace(value, '[^0-9]', '', 'g') FROM 3) WHEN regexp_replace(value, '[^0-9]', '', 'g') LIKE '0%' AND length(regexp_replace(value, '[^0-9]', '', 'g')) >= 10 THEN '44' || substring(regexp_replace(value, '[^0-9]', '', 'g') FROM 2) ELSE regexp_replace(value, '[^0-9]', '', 'g') END $$;
CREATE OR REPLACE FUNCTION prevent_duplicate_lead_identity() RETURNS TRIGGER LANGUAGE plpgsql AS $$ DECLARE address_key TEXT := normalize_lead_address(NEW.address); phone_key TEXT := normalize_lead_phone(NEW.phone); BEGIN PERFORM pg_advisory_xact_lock(hashtext(COALESCE(address_key, '') || '|' || COALESCE(phone_key, ''))); IF address_key IS NOT NULL AND length(address_key) > 0 AND EXISTS (SELECT 1 FROM leads WHERE id <> NEW.id AND normalize_lead_address(address) = address_key) THEN RAISE EXCEPTION 'A lead with this address already exists' USING ERRCODE = '23505'; END IF; IF phone_key IS NOT NULL AND length(phone_key) > 0 AND EXISTS (SELECT 1 FROM leads WHERE id <> NEW.id AND normalize_lead_phone(phone) = phone_key) THEN RAISE EXCEPTION 'A lead with this phone number already exists' USING ERRCODE = '23505'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS leads_unique_identity_guard ON leads;
CREATE TRIGGER leads_unique_identity_guard BEFORE INSERT OR UPDATE OF address, phone ON leads FOR EACH ROW EXECUTE FUNCTION prevent_duplicate_lead_identity();
